import{_ as n}from"./chunks/Audio.COine8Wh.js";import{c as t,o as r,j as i,G as o,ae as s,a}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"EMPOWERING COMMONSENSE WILDFIRE PREVENTION AND RESPONSE","description":"","frontmatter":{"legisId":"2025-06-12-empowering-commonsense-wildfire-prevention-and-response","title":"EMPOWERING COMMONSENSE WILDFIRE PREVENTION AND RESPONSE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/06/empowering-commonsense-wildfire-prevention-and-response/","publishDate":"2025-06-12T17:49:51-04:00"},"headers":[],"relativePath":"executive-orders/2025-06-12-empowering-commonsense-wildfire-prevention-and-response.md","filePath":"executive-orders/2025-06-12-empowering-commonsense-wildfire-prevention-and-response.md"}'),l={name:"executive-orders/2025-06-12-empowering-commonsense-wildfire-prevention-and-response.md"},g=Object.assign(l,{setup(d){return(p,e)=>(r(),t("div",null,[e[0]||(e[0]=i("h1",{id:"empowering-commonsense-wildfire-prevention-and-response",tabindex:"-1"},[a("EMPOWERING COMMONSENSE WILDFIRE PREVENTION AND RESPONSE "),i("a",{class:"header-anchor",href:"#empowering-commonsense-wildfire-prevention-and-response","aria-label":'Permalink to "EMPOWERING COMMONSENSE WILDFIRE PREVENTION AND RESPONSE"'},"​")],-1)),o(n),e[1]||(e[1]=s('<p>Published on Thursday, June 12, 2025</p><ul><li><p><strong>Background Context</strong></p><ul><li>The January 2025 wildfires in Los Angeles highlighted inadequate disaster response by state and local governments.</li><li>Slow responses often stem from mismanagement and lack of preparation, with outdated technology hindering firefighting efforts.</li></ul></li><li><p><strong>Federal Role</strong></p><ul><li>The Federal Government aims to enhance State and local wildfire response by streamlining capabilities and promoting technology-enabled strategies.</li></ul></li><li><p><strong>Action Items</strong></p><ul><li><p><strong>Within 90 Days:</strong></p><ul><li>Secretary of the Interior and Secretary of Agriculture to consolidate wildland fire programs for efficiency.</li><li>Expand partnerships and agreements to empower coordinated wildfire management across levels of government.</li><li>Consider modifications to EPA regulations that hinder preventative prescribed burns and fire retardants.</li><li>Promote innovative uses for woody biomass to reduce wildfire fuel loads.</li><li>Examine best practices in the electrical power sector to reduce wildfire ignition risks.</li><li>Review wildfire-related litigation involving electric utility companies to support prevention efforts.</li></ul></li><li><p><strong>Within 120 Days:</strong></p><ul><li>Secretary of Defense to declassify and release historical satellite data to enhance wildfire prevention and prediction.</li></ul></li><li><p><strong>Within 180 Days:</strong></p><ul><li>Develop a technology roadmap to improve wildfire fighting capabilities through advanced tools.</li><li>Identify and revise rules that hinder wildfire management and establish performance metrics for response efficacy.</li></ul></li><li><p><strong>Within 210 Days:</strong></p><ul><li>Evaluate the prioritization of excess military aircraft for wildfire mitigation purposes.</li></ul></li></ul></li><li><p><strong>Implementation and Authority</strong></p><ul><li>The order will be implemented according to applicable law and budget constraints.</li><li>It clarifies that it does not create enforceable rights or benefits against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/06/empowering-commonsense-wildfire-prevention-and-response/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/06/empowering-commonsense-wildfire-prevention-and-response/</a></p>',3))]))}});export{f as __pageData,g as default};
